const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const { GraphQLUpload, graphqlUploadExpress } = require('graphql-upload');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const UPLOAD_DIR = process.env.UPLOAD_DIR || '/var/uploads';

// Ensure upload directory exists
if (!fs.existsSync(UPLOAD_DIR)) {
  fs.mkdirSync(UPLOAD_DIR, { recursive: true });
}

const typeDefs = gql`
  scalar Upload

  type File {
    filename: String!
    mimetype: String!
    encoding: String!
    url: String!
  }

  type Query {
    files: [File]
  }

  type Mutation {
    uploadFile(file: Upload!): File!
    uploadAvatar(file: Upload!, userId: ID!): File!
  }
`;

const resolvers = {
  Upload: GraphQLUpload,

  Query: {
    files: () => {
      const files = fs.readdirSync(UPLOAD_DIR);
      return files.map(f => ({
        filename: f,
        mimetype: 'application/octet-stream',
        encoding: 'utf-8',
        url: `/static/${f}`
      }));
    }
  },

  Mutation: {
    uploadFile: async (_, { file }) => {
      const { createReadStream, filename, mimetype, encoding } = await file;

      // Generate a "safe" filename but preserve extension
      const ext = path.extname(filename);
      const baseName = path.basename(filename, ext);
      const safeBase = baseName.replace(/[^a-zA-Z0-9_-]/g, '_');
      const finalName = `${safeBase}_${Date.now()}${ext}`;

      const filePath = path.join(UPLOAD_DIR, finalName);

      await new Promise((resolve, reject) => {
        const stream = createReadStream();
        const out = fs.createWriteStream(filePath);
        stream.pipe(out);
        out.on('finish', resolve);
        out.on('error', reject);
      });

      // No file type validation - accepts any extension
      // No file size limit enforced at application level
      // No content-type verification against actual file bytes

      return {
        filename: finalName,
        mimetype,
        encoding,
        url: `/static/${finalName}`
      };
    },

    uploadAvatar: async (_, { file, userId }) => {
      const { createReadStream, filename, mimetype } = await file;

      // Intended for images only but no validation
      const ext = path.extname(filename);
      const finalName = `avatar_${userId}${ext}`;
      const filePath = path.join(UPLOAD_DIR, finalName);

      await new Promise((resolve, reject) => {
        const stream = createReadStream();
        const out = fs.createWriteStream(filePath);
        stream.pipe(out);
        out.on('finish', resolve);
        out.on('error', reject);
      });

      return {
        filename: finalName,
        mimetype,
        encoding: '7bit',
        url: `/static/${finalName}`
      };
    }
  }
};

const app = express();

// Serve uploaded files statically (enables execution of uploaded scripts)
app.use('/static', express.static(UPLOAD_DIR, {
  setHeaders: (res, filePath) => {
    // Attempt to set content-type based on extension
    if (filePath.endsWith('.html')) {
      res.setHeader('Content-Type', 'text/html');
    }
  }
}));

app.use(graphqlUploadExpress({ maxFileSize: 50_000_000, maxFiles: 10 }));

const server = new ApolloServer({
  typeDefs,
  resolvers,
  csrfPrevention: false,
  cache: 'bounded'
});

server.start().then(() => {
  server.applyMiddleware({ app, path: '/graphql' });
  app.listen(4000, () => {
    console.log(`Server ready at http://localhost:4000${server.graphqlPath}`);
  });
});
